package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__findDeserializer_TriageGen2Test {

    private DeserializationContext ctxt;
    private TypeIdResolver idResolver;
    private BeanProperty property;
    private JsonDeserializer<Object> mockDeserializer;
    private Map<String, JsonDeserializer<Object>> deserializers;
    private TestTypeDeserializer testInstance;

    // Concrete implementation to allow testing protected method
    private static class TestTypeDeserializer extends TypeDeserializerBase {
        protected Map<String, JsonDeserializer<Object>> _deserializers = new HashMap<>();
        protected JavaType _baseType;

        protected TestTypeDeserializer(JavaType baseType, TypeIdResolver idRes, String typePropertyName, 
                                      boolean typeIdVisible, Class<?> defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
            this._baseType = baseType;
        }

        // Exposure for testing
        public JsonDeserializer<Object> callFindDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return _findDeserializer(ctxt, typeId);
        }

        // Overriding internal field access via reflection/mocking is hard, 
        // so we override the logic or use the protected access if possible.
        // Since _deserializers is a field in the base class, we must use reflection to inject it.
        public void setDeserializers(Map<String, JsonDeserializer<Object>> map) throws Exception {
            java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_deserializers");
            field.setAccessible(true);
            field.set(this, map);
        }

        public void setBaseType(JavaType baseType) throws Exception {
            java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_baseType");
            field.setAccessible(true);
            field.set(this, baseType);
        }

        @Override public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() { return null; }
        @Override public String baseTypeName() { return null; }
        @Override public com.fasterxml.jackson.databind.jsontype.impl.TypeDeserializer forProperty(BeanProperty prop) { return null; }
    }

    @Before
    public void setUp() throws Exception {
        ctxt = mock(DeserializationContext.class);
        idResolver = mock(TypeIdResolver.class);
        property = mock(BeanProperty.class);
        mockDeserializer = mock(JsonDeserializer.class);
        deserializers = new HashMap<>();

        testInstance = new TestTypeDeserializer(null, idResolver, "type", true, Object.class);
        testInstance.setDeserializers(deserializers);
        testInstance.setBaseType(null);
    }

    @Test
    public void testFindDeserializer_AlreadyInMap() throws IOException {
        String typeId = "existing";
        deserializers.put(typeId, mockDeserializer);

        JsonDeserializer<Object> result = testInstance.callFindDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
        verifyNoInteractions(idResolver, ctxt);
    }

    @Test
    public void testFindDeserializer_TypeIdIsNull_ReturnsDefaultImpl() throws IOException {
        String typeId = "unknown";
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);

        // Mocking protected method _findDefaultImplDeserializer is tricky, 
        // we use a spy to control its return value
        TestTypeDeserializer spyInstance = spy(testInstance);
        doReturn(mockDeserializer).when(spyInstance)._findDefaultImplDeserializer(ctxt);

        JsonDeserializer<Object> result = spyInstance.callFindDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
        assertEquals(mockDeserializer, deserializers.get(typeId));
        verify(spyInstance)._findDefaultImplDeserializer(ctxt);
    }

    @Test
    public void testFindDeserializer_TypeIdIsNull_ReturnsHandleUnknown() throws IOException {
        String typeId = "unknown";
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);

        TestTypeDeserializer spyInstance = spy(testInstance);
        doReturn(null).when(spyInstance)._findDefaultImplDeserializer(ctxt);
        doReturn(mockDeserializer).when(spyInstance)._handleUnknownTypeId(eq(ctxt), eq(typeId), eq(idResolver), any());

        JsonDeserializer<Object> result = spyInstance.callFindDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
        verify(spyInstance)._handleUnknownTypeId(eq(ctxt), eq(typeId), eq(idResolver), any());
    }

    @Test
    public void testFindDeserializer_WithTypeFound_NoBaseType() throws IOException {
        String typeId = "myType";
        JavaType type = mock(JavaType.class);
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(type);
        when(ctxt.findContextualValueDeserializer(eq(type), any())).thenReturn(mockDeserializer);

        JsonDeserializer<Object> result = testInstance.callFindDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
        verify(ctxt).findContextualValueDeserializer(eq(type), any());
    }

    @Test
    public void testFindDeserializer_WithTypeFound_WithBaseTypeNarrowing() throws IOException {
        String typeId = "myType";
        JavaType baseType = mock(JavaType.class);
        JavaType type = mock(JavaType.class);

        // Setup: BaseType class matches Type class to trigger narrowing
        when(baseType.getClass()).thenReturn(type.getClass());
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(type);
        when(type.getRawClass()).thenReturn(String.class);
        when(baseType.narrowBy(String.class)).thenReturn(type);
        when(ctxt.findContextualValueDeserializer(eq(type), any())).thenReturn(mockDeserializer);

        testInstance.setBaseType(baseType);

        JsonDeserializer<Object> result = testInstance.callFindDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
        verify(baseType).narrowBy(String.class);
        verify(ctxt).findContextualValueDeserializer(eq(type), any());
    }

    @Test
    public void testFindDeserializer_WithTypeFound_DifferentBaseTypeClass() throws IOException {
        String typeId = "myType";
        JavaType baseType = mock(JavaType.class);
        JavaType type = mock(JavaType.class);

        // Setup: BaseType class does NOT match Type class
        when(baseType.getClass()).thenReturn(Object.class);
        when(type.getClass()).thenReturn(JavaType.class); // different
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(type);
        when(ctxt.findContextualValueDeserializer(eq(type), any())).thenReturn(mockDeserializer);

        testInstance.setBaseType(baseType);

        JsonDeserializer<Object> result = testInstance.callFindDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
        verify(baseType, never()).narrowBy(any());
    }
}
